import os
from abc import ABCMeta
from six import with_metaclass
from ute_syslog import ute_syslog
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.log_analysis.event import SyslogCollected
from taf.ul.ettf.logging.collector import Collector
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.typed.custom_types import Filepath, List, Ip
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.utils.functions import get_eth_ip
from taf.ul.ettf.utils.robot_handlers import with_callback_name

logger = custom_logger('SyslogCollectorLogger')


class SyslogCollector(with_metaclass(ABCMeta, Collector)):
    @typed(logs_directory=Filepath(), alias=str, remote_hosts=List(Ip()), eth_name=str)
    def __init__(self, logs_directory, alias, remote_hosts, eth_name):
        self._syslog_lib = ute_syslog
        self._logs_directory = logs_directory
        self._remote_hosts = remote_hosts if remote_hosts else [b'127.0.0.1'.decode('utf-8')]
        self._base_alias = alias
        self._eth_name = eth_name

    def start(self):
        for remote_host in self._remote_hosts:
            self._start_syslog_instance(remote_host=remote_host)

    @with_callback_name('Stop Syslog Collector')
    def stop(self):
        for remote_host in self._remote_hosts:
            self._syslog_lib().collect_syslog_results(alias=self._alias(remote_host))
            log_path = os.path.join(self._logs_directory, '{}_{}.log'.format(self._base_alias, remote_host))
            Notifier().notify(SyslogCollected(log_path))

    def _start_syslog_instance(self, remote_host):
        lmp_ip = get_eth_ip(self._eth_name, remote_host)
        self._syslog_lib().start_syslog(
            log_dir=self._logs_directory,
            log_name=self._log_filename(self._base_alias, remote_host),
            ip=lmp_ip,
            host_ip=remote_host,
            alias=self._alias(remote_host))
        logger.debug("Syslog started with alias {}, IP: {}".format(self._base_alias, lmp_ip))

    def _alias(self, remote_host):
        return '{}_{}'.format(self._base_alias, remote_host) if remote_host not in (None, "127.0.0.1") else self._base_alias

    def _log_filename(self, log_prefix, remote_host):
        return '{}_{}.log'.format(log_prefix, remote_host)


class GnbSyslogCollector(SyslogCollector):
    ALIAS = 'gnb_syslog'
    ETH_NAME = "eth1"

    def __init__(self, logs_directory, remote_hosts):
        super(GnbSyslogCollector, self).__init__(
            logs_directory=logs_directory,
            remote_hosts=remote_hosts,
            alias=self.ALIAS,
            eth_name=self.ETH_NAME
        )

    @with_callback_name('Stop Gnb Syslog Collector')
    def stop(self):
        return super(GnbSyslogCollector, self).stop()


